app.get("/hello", (req, res) => {
    const name = req.query.name;
    const safeName = String(name ?? "").replace(/[&<>"']/g, (ch) => {
        switch (ch) {
            case "&": return "&amp;";
            case "<": return "&lt;";
            case ">": return "&gt;";
            case '"': return "&quot;";
            case "'": return "&#39;";
            default: return ch;
        }
    });
    res.send("<h1>Hello " + safeName + "</h1>");
});
